import React from 'react';
import { Form, Input, Button, InputNumber } from '@cloud-materials/common';
import CAgreement from '..';

const FormItem = Form.Item;

export default () => {
  return (
    <div style={{ width: '400px' }}>
      <Form
        initialValues={{ name: 'admin', age: '1', deal: true }}
        autoComplete="off"
        onSubmit={v => {
          alert('提交成功');
          console.log('收集到的value', v);
        }}
      >
        <FormItem label="name" field="name" rules={[{ required: true }]}>
          <Input placeholder="please enter your username" />
        </FormItem>
        <FormItem label="Age" field="age" rules={[{ required: true, type: 'number', min: 0, max: 99 }]}>
          <InputNumber placeholder="please enter your age" />
        </FormItem>
        <FormItem
          label=" "
          field="deal"
          rules={[
            {
              validator(value, callback) {
                if (value) callback();
                else callback(' ');
              },
            },
          ]}
        >
          {(_, form) => {
            // 获取错误状态
            const errorObj = form.getFieldError('deal');
            return (
              <CAgreement
                validateStatusError={errorObj ? true : false}
                prefix="我已阅读并同意"
                errorToolTip="请阅读相关协议，并勾选同意。"
                link={[
                  {
                    linkUrl: 'https://www.google.com',
                    linkDesc: '《云服务器条款》',
                  },
                  {
                    linkUrl: 'https://www.google.com',
                    linkDesc: '《数据库实例条款》',
                  },
                  {
                    linkUrl: 'https://www.google.com',
                    linkDesc: '《块存储条款》',
                  },
                ]}
              />
            );
          }}
        </FormItem>
        <FormItem wrapperCol={{ offset: 5 }}>
          <Button type="primary" htmlType="submit" style={{ marginRight: 24 }}>
            Submit
          </Button>
        </FormItem>
      </Form>
    </div>
  );
};

import React from 'react';
import { CForm } from '@cloud-materials/common';

export default () => {
  const config = CForm.defineConfig({
    fields: [
      {
        name: 'section1',
        type: 'VoidField',
        title: '基本信息',
        decoratorOptions: {
          component: 'Section',
        },
        fields: [
          {
            name: 'name',
            type: 'Field',
            title: '名称',
            initialValue: 'mongodb',
            decoratorOptions: {
              component: 'FormItem',
            },
            required: true,
            componentOptions: {
              component: 'Input',
            },
          },
          {
            name: 'agree',
            title: '协议',
            type: 'Field',
            initialValue: true,
            decoratorOptions: CForm.defineDecoratorOptions('FormItem'),
            componentOptions: CForm.defineComponentOption('CAgreement', {
              prefix: '我已阅读并同意',
              errorToolTip: '请阅读相关协议，并勾选同意。',
              link: [
                {
                  linkUrl: 'https://www.google.com',
                  linkDesc: '《云服务器条款》',
                },
                {
                  linkUrl: 'https://www.google.com',
                  linkDesc: '《实例条款》',
                },
              ],
            }),
          },
          {
            name: 'age',
            type: 'Field',
            title: '年龄',
            initialValue: '12',
            decoratorOptions: {
              component: 'FormItem',
            },
            required: true,
            componentOptions: {
              component: 'Input',
            },
          },
        ],
      },
    ],
    residentContent: [
      {
        field: {
          name: 'preview',
          type: 'VoidField',
          componentOptions: CForm.defineComponentOption('ConfigPreview', {
            config: [
              {
                title: '配置详情',
                fieldIndex: ['name'],
                formatter: ({ fieldKey, title, value }, _) => {
                  return {
                    fieldKey,
                    title: title + '：',
                    value: value,
                  };
                },
              },
            ],
          }),
        },
      },
      {
        field: {
          name: 'deal',
          type: 'Field',
          componentOptions: CForm.defineComponentOption('CAgreement', {
            scene: 'card',
            prefix: '我已阅读并同意',
            errorToolTip: '请阅读相关协议，并勾选同意。',
            link: [
              {
                linkUrl: 'https://www.google.com',
                linkDesc: '《云服务器条款》',
              },
              {
                linkUrl: 'https://www.google.com',
                linkDesc: '《实例条款》',
              },
            ],
          }),
        },
      },
      { buttonType: 'confirm' },
    ],
    footer: {
      right: [
        {
          // 取消操作无默认行为
          buttonType: 'cancel',
          props: {
            onClick: () => {
              alert('点击取消');
            },
          },
        },
        { buttonType: 'confirm' },
      ],
    },
    onSubmit: value => {
      console.log('value', value);
      alert('提交订单成功');
    },
  });

  return (
    <div style={{ width: '100%', height: 800, overflow: 'auto' }}>
      <CForm
        config={config}
        defaultDecoratorProps={{
          isFullPage: true,
        }}
      />
    </div>
  );
};
